import React from "react";
import Grid from "@material-ui/core/Grid";

function RSPaper(props) {
  return (
    <Grid
      container
      direction="column"
      justify="center"
      alignItems="center"
      style={{ height: "95vh" }}
    >
      <a
        href="/assets/OnTheConstructionOfReedSolomonCodes.pdf"
        download=""
        className="like-link"
      >
        <h2 className="montserrat-medium text-center">
          If the download does not begin after 5 seconds, click this text
        </h2>
      </a>
    </Grid>
  );
}

export default RSPaper;
